export const handler = async (input) => {
  const byDevice = (input.model ?? '') !== '' || (input.brands ?? []).length > 0;
  const compat = new Set(input.compat.rows.map((r) => r.product_id));
  const stock = new Set(input.stock.rows.map((r) => r.product_id));
  const list = input.products.rows.filter((p) => (!byDevice || compat.has(p.product_id)) && (!input.inStock || stock.has(p.product_id)));
  list.sort((a, b) => b.rank_score - a.rank_score || (a.sku < b.sku ? -1 : a.sku > b.sku ? 1 : 0));
  const size = input.pageSize ?? 24;
  const page = input.page ?? 0;
  return { skus: list.slice(page * size, page * size + size).map((p) => p.sku) };
};

