SELECT p.sku FROM ${S}.products p WHERE p.status = 'active'
{{#if colour}} AND p.colour = {{ colour }} {{/if}}
{{#if quality}} AND p.quality = {{ quality }} {{/if}}
{{#if partType}} AND p.part_type = {{ partType }} {{/if}}
{{#if model or brands}} AND EXISTS (SELECT 1 FROM ${S}.compatibility c JOIN ${S}.devices d ON d.device_id = c.device_id WHERE c.product_id = p.product_id {{#if model}} AND d.model_name = {{ model }} {{/if}} {{#if brands}} AND d.brand IN ({{ brands }}) {{/if}}) {{/if}}
{{#if inStock}} AND p.product_id IN (SELECT product_id FROM ${S}.inventory GROUP BY product_id HAVING SUM(qty) > 0) {{/if}}
ORDER BY p.rank_score DESC, p.sku
LIMIT {{ pageSize ?? 24 }} OFFSET {{ (page ?? 0) * (pageSize ?? 24) }}
